import React, { useMemo, useState } from 'react';
import LocalFireDepartmentIcon from '@mui/icons-material/LocalFireDepartment';
import BoltIcon from '@mui/icons-material/Bolt';
import LocalShippingIcon from '@mui/icons-material/LocalShipping';
import Inventory2Icon from '@mui/icons-material/Inventory2';
import ShoppingBagOutlinedIcon from '@mui/icons-material/ShoppingBagOutlined';
import RecyclingIcon from '@mui/icons-material/Recycling';
import { Alert, Box, Chip, Stack, Typography } from '@mui/material';
import type { SvgIconComponent } from '@mui/icons-material';
import { formatCo2eFromKg } from '../../constants/carbonVisualization';
import { buildIso14064DashboardCategories } from '../../utils/iso14064DashboardCategories';

type ScopeBlock = {
  total?: number;
  breakdown?: Record<string, number> | null;
  ghgCategories?: Record<string, number> | null;
} | null;

export type IsoLedgerSummary = {
  isoCategories?: Array<{ id?: string; kgCo2e?: number }>;
  isoSubcategories?: Array<{ id?: string; subcategory?: string; kgCo2e?: number }>;
  unallocatedScope3Kg?: number;
};

export type Iso14064CategoryStripProps = {
  scope1?: ScopeBlock;
  scope2?: ScopeBlock;
  scope3?: ScopeBlock;
  /** CarbonTwin keeps Scope 3 as one total, so Categories 3–6 stay explained without a split. */
  separateScope3?: boolean;
  /** Same ISO totals the CSV workbook and the report use. These quantities replace the scope-key estimate. */
  ledger?: IsoLedgerSummary | null;
  /** Ties the categories to the organization boundary on the carbon page, or to twin zones. */
  lead?: string;
  /** Short note under a category, such as which CarbonTwin zone it covers. */
  placementByCategory?: Record<string, string>;
};

const CATEGORY_FACE: Record<string, { name: string; color: string; Icon: SvgIconComponent }> = {
  cat1_direct: { name: 'Direct', color: '#1B5E20', Icon: LocalFireDepartmentIcon },
  cat2_imported_energy: { name: 'Imported energy', color: '#1565C0', Icon: BoltIcon },
  cat3_transport: { name: 'Transportation', color: '#EF6C00', Icon: LocalShippingIcon },
  cat4_products_used: { name: 'Products used', color: '#6A1B9A', Icon: Inventory2Icon },
  cat5_product_use: { name: 'Product use', color: '#00838F', Icon: ShoppingBagOutlinedIcon },
  cat6_other: { name: 'Other sources', color: '#6D4C41', Icon: RecyclingIcon },
};

const ledgerKg = (rows: Array<{ id?: string; kgCo2e?: number }> | undefined, id: string) => {
  const match = (rows || []).find((row) => row.id === id);
  return match ? Number(match.kgCo2e) || 0 : null;
};

const sharePercent = (part: number, whole: number) => (
  whole > 0 ? Math.round((part / whole) * 1000) / 10 : 0
);

const Iso14064CategoryStrip: React.FC<Iso14064CategoryStripProps> = ({
  scope1,
  scope2,
  scope3,
  separateScope3 = true,
  ledger,
  lead,
  placementByCategory,
}) => {
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const view = useMemo(() => {
    const hasLedger = (ledger?.isoCategories || []).some((row) => row.id);
    const built = buildIso14064DashboardCategories(
      hasLedger ? { separateScope3: true } : { scope1, scope2, scope3, separateScope3 }
    );
    if (!hasLedger) return built;
    return {
      ...built,
      unallocatedScope3Kg: Number(ledger?.unallocatedScope3Kg) || 0,
      scope3UnseparatedKg: 0,
      categories: built.categories.map((category) => {
        const categoryKg = ledgerKg(ledger?.isoCategories, category.id);
        return {
          ...category,
          kgCo2e: categoryKg == null ? category.kgCo2e : categoryKg,
          notModelled: category.id === 'cat5_product_use' && !(categoryKg && categoryKg > 0),
          subcategories: category.subcategories.map((subcategory) => {
            const subcategoryKg = ledgerKg(ledger?.isoSubcategories, subcategory.id);
            return {
              ...subcategory,
              kgCo2e: subcategoryKg == null ? 0 : subcategoryKg,
            };
          }),
        };
      }),
    };
  }, [scope1, scope2, scope3, separateScope3, ledger]);
  const measuredKg = view.categories.reduce((sum, category) => sum + (category.kgCo2e || 0), 0)
    + view.unallocatedScope3Kg
    + view.scope3UnseparatedKg;
  const unit: 'kg' | 't' = measuredKg >= 1000 ? 't' : 'kg';
  const slices = [
    ...view.categories
      .filter((category) => (category.kgCo2e || 0) > 0)
      .map((category) => ({
        id: category.id,
        label: CATEGORY_FACE[category.id]?.name || category.label,
        color: CATEGORY_FACE[category.id]?.color || '#607D8B',
        kg: category.kgCo2e || 0,
      })),
    ...(view.scope3UnseparatedKg > 0
      ? [{ id: 'scope3', label: 'Scope 3', color: '#78909C', kg: view.scope3UnseparatedKg }]
      : []),
    ...(view.unallocatedScope3Kg > 0
      ? [{ id: 'unallocated', label: 'Unallocated', color: '#F9A825', kg: view.unallocatedScope3Kg }]
      : []),
  ];
  let cursor = 0;
  const gradient = slices.length
    ? `conic-gradient(${slices.map((slice) => {
      const start = cursor;
      cursor += (slice.kg / measuredKg) * 100;
      return `${slice.color} ${start}% ${cursor}%`;
    }).join(', ')})`
    : 'conic-gradient(#E0E0E0 0% 100%)';
  const toggle = (id: string) => setSelectedId((current) => (current === id ? null : id));

  return (
    <Box
      component="section"
      data-testid="iso-14064-category-strip"
      aria-label="ISO 14064-1 categories"
      sx={{ mb: 3, p: { xs: 1.5, sm: 2 }, border: 1, borderColor: 'divider', borderRadius: 2 }}
    >
      <Typography variant="subtitle1" sx={{ fontWeight: 800 }}>
        ISO 14064-1:2018 categories
      </Typography>
      <Typography variant="body2" color="text.secondary" sx={{ mt: 0.5, mb: 2, maxWidth: 760 }}>
        {lead || 'The same inventory, shown as six categories. Select a category to focus it.'}
      </Typography>
      <Stack direction={{ xs: 'column', sm: 'row' }} spacing={2} alignItems={{ sm: 'center' }} sx={{ mb: 2 }}>
        <Box
          data-testid="iso-category-share"
          aria-hidden
          sx={{
            width: 168,
            height: 168,
            flex: '0 0 auto',
            borderRadius: '50%',
            background: gradient,
            display: 'grid',
            placeItems: 'center',
            alignSelf: { xs: 'center', sm: 'auto' },
          }}
        >
          <Box
            sx={{
              width: 104,
              height: 104,
              borderRadius: '50%',
              bgcolor: 'background.paper',
              display: 'grid',
              placeItems: 'center',
              textAlign: 'center',
              px: 1,
            }}
          >
            <Box>
              <Typography variant="subtitle1" sx={{ fontWeight: 800, lineHeight: 1.1 }}>
                {formatCo2eFromKg(measuredKg, { unit })}
              </Typography>
              <Typography variant="caption" color="text.secondary">inventory</Typography>
            </Box>
          </Box>
        </Box>
        <Stack spacing={0.75} sx={{ flex: '1 1 280px', maxWidth: 460 }}>
          {view.categories.map((category) => {
            const face = CATEGORY_FACE[category.id];
            const kg = category.kgCo2e;
            const selected = selectedId === category.id;
            return (
              <Box
                key={category.id}
                component="button"
                type="button"
                onClick={() => toggle(category.id)}
                aria-pressed={selected}
                sx={{
                  display: 'flex',
                  alignItems: 'center',
                  gap: 1,
                  width: '100%',
                  p: 0.5,
                  border: 0,
                  borderRadius: 1,
                  bgcolor: selected ? 'action.selected' : 'transparent',
                  color: 'inherit',
                  font: 'inherit',
                  cursor: 'pointer',
                  textAlign: 'left',
                  opacity: selectedId && !selected ? 0.45 : 1,
                }}
              >
                <Box sx={{ width: 12, height: 12, borderRadius: '50%', bgcolor: face?.color || 'grey.500', flex: '0 0 auto' }} />
                <Typography variant="body2" sx={{ fontWeight: 700, flex: 1 }}>
                  {category.clause.replace('ISO 14064-1:2018 ', '')} · {face?.name}
                </Typography>
                <Typography variant="body2" sx={{ fontWeight: 800 }}>
                  {kg == null ? 'Not separated' : formatCo2eFromKg(kg, { unit })}
                </Typography>
              </Box>
            );
          })}
        </Stack>
      </Stack>
      <Box
        sx={{
          display: 'grid',
          gridTemplateColumns: { xs: '1fr', md: '1fr 1fr', lg: '1fr 1fr 1fr' },
          gap: 1.5,
        }}
      >
        {view.categories.map((category) => {
          const face = CATEGORY_FACE[category.id];
          const Icon = face?.Icon;
          const number = category.clause.match(/Category (\d)/)?.[1] || '';
          const kg = category.kgCo2e || 0;
          const measuredSubs = category.subcategories.filter((subcategory) => (subcategory.kgCo2e || 0) > 0);
          const selected = selectedId === category.id;
          return (
            <Box
              key={category.id}
              component="button"
              type="button"
              data-testid={`iso-category-${category.id}`}
              aria-label={`${category.clause}. ${category.label}. ${category.description} ${category.ghgProtocolMapping}`}
              aria-pressed={selected}
              onClick={() => toggle(category.id)}
              sx={{
                width: '100%',
                p: 1.5,
                textAlign: 'left',
                color: 'inherit',
                font: 'inherit',
                border: 1,
                borderColor: selected ? (face?.color || 'primary.main') : 'divider',
                borderTop: `4px solid ${face?.color || '#607D8B'}`,
                borderRadius: 2,
                bgcolor: 'background.paper',
                cursor: 'pointer',
                opacity: selectedId && !selected ? 0.45 : 1,
              }}
            >
              <Stack direction="row" spacing={1} alignItems="center">
                <Box
                  sx={{
                    width: 36,
                    height: 36,
                    borderRadius: '50%',
                    bgcolor: face?.color || 'grey.600',
                    color: '#fff',
                    display: 'grid',
                    placeItems: 'center',
                    flex: '0 0 auto',
                  }}
                >
                  {Icon ? <Icon sx={{ fontSize: 18 }} /> : null}
                </Box>
                <Box sx={{ minWidth: 0, flex: 1 }}>
                  <Typography variant="caption" sx={{ fontWeight: 800, color: face?.color }}>
                    {number}
                  </Typography>
                  <Typography variant="body2" sx={{ fontWeight: 800, lineHeight: 1.2 }}>
                    {face?.name || category.label}
                  </Typography>
                </Box>
                <Typography variant="subtitle2" sx={{ fontWeight: 800 }}>
                  {category.kgCo2e == null ? '—' : formatCo2eFromKg(category.kgCo2e, { unit })}
                </Typography>
              </Stack>
              <Box sx={{ mt: 1, height: 8, borderRadius: 99, bgcolor: 'action.hover', overflow: 'hidden' }}>
                <Box
                  sx={{
                    width: `${Math.min(100, sharePercent(kg, measuredKg))}%`,
                    height: '100%',
                    bgcolor: face?.color || 'grey.500',
                  }}
                />
              </Box>
              <Typography variant="caption" color="text.secondary" display="block" sx={{ mt: 0.5 }}>
                {category.kgCo2e == null
                  ? 'Not separated on this page'
                  : `${sharePercent(kg, measuredKg)}% of this inventory`}
              </Typography>
              {category.notModelled ? <Chip size="small" label="Not modelled" sx={{ mt: 0.75 }} /> : null}
              {placementByCategory?.[category.id] ? (
                <Typography variant="caption" display="block" sx={{ mt: 0.75, fontWeight: 700 }}>
                  {placementByCategory[category.id]}
                </Typography>
              ) : null}
              <Stack spacing={0.75} sx={{ mt: measuredSubs.length ? 1.25 : 0 }}>
                {measuredSubs.map((subcategory) => {
                  const subKg = subcategory.kgCo2e || 0;
                  const width = kg > 0 ? Math.max(6, Math.min(100, (subKg / kg) * 100)) : 0;
                  return (
                    <Box
                      key={subcategory.id}
                      data-testid={`iso-subcategory-${subcategory.id}`}
                      aria-label={`${subcategory.label}. ${subcategory.detail} ${subcategory.ghgProtocolMapping}`}
                    >
                      <Stack direction="row" justifyContent="space-between" spacing={1} alignItems="baseline">
                        <Typography variant="caption" sx={{ fontWeight: 700 }}>{subcategory.label}</Typography>
                        <Typography variant="caption" sx={{ flex: '0 0 auto', whiteSpace: 'nowrap' }}>
                          {formatCo2eFromKg(subKg, { unit })}
                        </Typography>
                      </Stack>
                      <Box sx={{ mt: 0.25, height: 6, borderRadius: 99, bgcolor: 'action.hover', overflow: 'hidden' }}>
                        <Box sx={{ width: `${width}%`, height: '100%', bgcolor: face?.color || 'grey.500', opacity: 0.85 }} />
                      </Box>
                    </Box>
                  );
                })}
              </Stack>
            </Box>
          );
        })}
      </Box>
      {view.scope3UnseparatedKg > 0 ? (
        <Typography variant="body2" data-testid="iso-scope3-unseparated" sx={{ mt: 1.5 }}>
          Scope 3 on this page is {formatCo2eFromKg(view.scope3UnseparatedKg, { unit })} and is not split into Categories 3, 4, 5 and 6. Those category quantities are on the carbon footprint page, where each activity has a category key.
        </Typography>
      ) : null}
      {view.unallocatedScope3Kg > 0 ? (
        <Alert severity="warning" data-testid="iso-unallocated-scope3" sx={{ mt: 1.5 }}>
          Unallocated Scope 3: {formatCo2eFromKg(view.unallocatedScope3Kg, { unit })}. No category key was present, so no share was assigned.
        </Alert>
      ) : null}
    </Box>
  );
};

export default Iso14064CategoryStrip;
